  font-weight: 500;
  margin-top: 8px;
  border: none;
  cursor: pointer;
  transition: opacity 0.15s, transform 0.15s;
  font-family: inherit;
}
.link-pill:hover { opacity: 0.9; transform: translateY(-1px); }
.link-pill.secondary {
  background: rgba(0, 0, 0, 0.06);
  color: var(--text-primary);
}
.actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 8px; }

/* About hero */
.hero {
  display: flex;
  align-items: flex-start;
  gap: 32px;
  margin-top: 4px;
}
.avatar {
  width: 96px;
  height: 96px;
  border-radius: 26%;
  background: linear-gradient(135deg, #ffb88c, #ff7e87 50%, #b48aff);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 36px;
  font-weight: 600;
  letter-spacing: -0.02em;
  box-shadow: 0 10px 30px rgba(255, 126, 135, 0.3);
}
.hero-text { flex: 1; min-width: 0; }

/* Project hero/artwork */
.artwork {
  aspect-ratio: 16 / 7;
  border-radius: 22px;
  /* Use individual margin properties so the bleed-left class can still
     override margin-left without being clobbered by a shorthand. */
  margin-top: 14px;
  margin-right: 0;
  margin-bottom: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.01em;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.08);
  position: relative;
  overflow: hidden;
}
.artwork::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.32), transparent 55%);
}
.artwork span { position: relative; z-index: 1; }

/* Image placeholders */
.image-placeholder {
  background: linear-gradient(135deg, #f4f4f6, #e9eaf0);
  border: 1px dashed rgba(0, 0, 0, 0.12);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 12px;
  text-align: center;
  padding: 24px;
  aspect-ratio: 16 / 9;
  margin: 14px 0;
}
.image-placeholder .ph-icon {
  width: 28px; height: 28px;
  opacity: 0.5;
}
.image-placeholder .ph-label {
  font-weight: 500;
  color: var(--text-secondary);
  font-size: 13px;
}
.image-placeholder .ph-hint {
  font-size: 11px;
  color: var(--text-tertiary);
  max-width: 320px;
  line-height: 1.4;
}
.image-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin: 14px 0;
}
.image-row .image-placeholder { margin: 0; aspect-ratio: 4 / 3; }
.image-placeholder.tall { aspect-ratio: 4 / 5; }
.image-placeholder.wide { aspect-ratio: 21 / 9; }

/* Process / outcomes lists */
.pill-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 4px 0 22px;
}
.pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  background: rgba(0, 0, 0, 0.04);
  border-radius: 999px;
}

.outcome-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 14px 0 22px;
}
.outcome-card {
  background: rgba(0, 0, 0, 0.025);
  border-radius: 12px;
  padding: 16px 18px;
}
.outcome-card .n {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.outcome-card .l {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 4px;
  line-height: 1.4;
}

.contact-block {
  background: rgba(0, 122, 255, 0.06);
  border: 1px solid rgba(0, 122, 255, 0.15);
  border-radius: 14px;
  padding: 22px 24px;
  margin-top: 36px;
}
.contact-block h3 {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 6px;
}
.contact-block p {
  color: var(--text-secondary);
  font-size: 14px;
  margin-bottom: 14px;
}
.contact-links { display: flex; gap: 8px; flex-wrap: wrap; }

