/* Content area — no card, full-bleed */
.content {
  position: fixed;
  inset: 0;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  display: flex;
  flex-direction: row;
  scrollbar-width: none;
  -ms-overflow-style: none;
  z-index: 1;
  scroll-padding-left: var(--snap-offset);
}
.content::-webkit-scrollbar { display: none; }

/* Spacer pushes the first panel to start at the snap position */
.content-spacer {
  flex: 0 0 var(--snap-offset);
  height: 100%;
  pointer-events: none;
}

.panel {
  flex: 0 0 calc(100vw - var(--snap-offset));
  width: calc(100vw - var(--snap-offset));
  height: 100vh;
  overflow-y: auto;
  overflow-x: hidden;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  /* padding-left = bleed + 56 (= navbar-overlap + breathing). With
     padding-right = 56 and panel-inner auto-margins, the inner column
     auto-centers exactly within the visible area (right of navbar). */
  padding: 72px var(--pad-right) 80px var(--pad-left);
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.panel::-webkit-scrollbar { display: none; }

.panel-inner {
  max-width: var(--inner-max);
  margin: 0 auto;          /* auto-centers in panel content area */
  will-change: transform;
}

/* Sections that bleed across the panel (artwork). The element spans
   panel.left → panel.right, so when the panel is scrolled out the
   gradient fills the navbar area continuously. Inner padding pushes
   the label so it still lines up with the centered title above. */
.bleed-left {
  /* CSS magic: 50% - 50vw + snap-offset/2 gives the negative-margin
     needed to reach panel.left from any auto-centered child, because
     50% (of parent) sits at the visible-area center. */
  margin-left: calc(50% - 50vw + var(--snap-offset) / 2);
  margin-right: calc(50% - 50vw + var(--snap-offset) / 2);
  width: calc(100vw - var(--snap-offset));
  max-width: none;
  padding-left: calc(50vw - var(--snap-offset) / 2 - 50%);
  padding-right: calc(50vw - var(--snap-offset) / 2 - 50%);
  box-sizing: border-box;
}

/* Typography */
.greeting {
  font-size: 14px;
  color: var(--text-tertiary);
  margin-bottom: 6px;
  font-weight: 500;
}
.eyebrow {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 10px;
  font-weight: 600;
}
h1.title {
  font-size: 46px;
  line-height: 1.08;
  letter-spacing: -0.025em;
  font-weight: 700;
  margin-bottom: 18px;
}
h2.section-title {
  font-size: 24px;
  line-height: 1.2;
  letter-spacing: -0.01em;
  font-weight: 600;
  margin: 40px 0 14px;
}
.lede {
  font-size: 20px;
  line-height: 1.5;
  color: var(--text-secondary);
  margin-bottom: 28px;
  font-weight: 400;
}
p.body {
  font-size: 15px;
  line-height: 1.7;
  color: #3a3a3c;
  margin-bottom: 16px;
}

.meta-row {
  display: flex;
  gap: 40px;
  padding: 20px 0;
  border-top: 1px solid var(--divider);
  border-bottom: 1px solid var(--divider);
  margin: 28px 0 32px;
  flex-wrap: wrap;
}
.meta-row .label {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 5px;
  font-weight: 500;
}
.meta-row .value {
  font-size: 14px;
  font-weight: 500;
}

.link-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  background: var(--accent);
  color: white;
  border-radius: 999px;
  text-decoration: none;
  font-size: 13px;

