file.content:
  border-color: var(--accent);
  background: white;
  box-shadow: 0 0 0 3px rgba(0, 122, 255, 0.12);
}
.contact-form textarea {
  min-height: 96px;
  max-height: 240px;
}
.contact-form button[type="submit"] {
  align-self: flex-start;
}
.form-success {
  background: rgba(52, 211, 153, 0.12);
  color: #047857;
  border: 1px solid rgba(52, 211, 153, 0.3);
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 13px;
  display: none;
}
.form-success.show { display: block; }

.calendly-card {
  background: linear-gradient(135deg, #007aff, #5e3aff);
  color: white;
  border-radius: 16px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
  box-shadow: 0 14px 36px rgba(0, 122, 255, 0.2);
}
.calendly-card h3 {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 6px;
}
.calendly-card p {
  font-size: 13px;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.86);
}
.calendly-card .cal-illustration {
  background: rgba(255, 255, 255, 0.16);
  border-radius: 12px;
  padding: 14px;
  margin: 6px 0;
  backdrop-filter: blur(10px);
}
.calendly-card .cal-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.9);
  padding: 6px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
}
