@media (max-width: 768px) {
  :root {
    --sidebar-width: 0px;
    --sidebar-gap: 0px;
    --bleed: 0px;
    --content-offset: 0px;
    --snap-offset: 0px;
    --pad-left: 20px;
    --pad-right: 20px;
  }

  /* Fully hide the desktop sidebar — !important guards against any
     transient flash before JS / media-query takes effect. */
  .sidebar,
  aside.sidebar { display: none !important; }

  .bottom-nav { display: flex; }

  /* Horizontal scroll on mobile is limited to About + Projects-list.
     The flex container only sees these two panels as snap targets. */
  .content {
    scroll-padding-left: 0;
  }
  .content-spacer { display: none; }

  .panel {
    padding: 28px 20px 110px 20px;
    width: 100vw;
    flex: 0 0 100vw;
    height: 100dvh;
  }
  .panel-inner { max-width: 100%; }

  /* Projects-list panel becomes the second tab in mobile */
  .panel[data-id="projects-list"] { display: block; }

  /* Individual project panels are removed from the horizontal flex flow
     and become full-screen overlays that slide in from the right when
     opened (iOS-style stack navigation). */
  .panel.is-project {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100dvh;
    flex: none;
    transform: translateX(100%);
    transition: transform 0.32s cubic-bezier(.2,.8,.2,1);
    z-index: 40;
    background: var(--bg);
    overflow-y: auto;
    overflow-x: hidden;
    padding-bottom: 40px; /* no bottom nav inside a project view */
    box-shadow: -8px 0 24px rgba(0, 0, 0, 0.06);
  }
  .panel.is-project.is-open { transform: translateX(0); }
  .panel.is-project.is-dragging { transition: none; }

  /* Hide bottom-nav while a project is open — back is via swipe / button */
  body.project-open .bottom-nav {
    transform: translateY(120%);
    opacity: 0;
    pointer-events: none;
    transition: transform 0.25s ease, opacity 0.25s ease;
  }
  .bottom-nav { transition: transform 0.25s ease, opacity 0.25s ease; }

  /* Back button shown inside a project view on mobile */
  .mobile-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(0, 0, 0, 0.05);
    border: none;
    padding: 8px 14px 8px 10px;
    border-radius: 999px;
    font-family: inherit;
    font-size: 14px;
    color: var(--text-primary);
    font-weight: 500;
    margin-bottom: 18px;
    cursor: pointer;
  }
  .mobile-back-btn svg { width: 18px; height: 18px; }

  /* === Typography (mobile) === */
  h1.title { font-size: 30px; line-height: 1.12; letter-spacing: -0.02em; margin-bottom: 14px; }
  h2.section-title { font-size: 20px; margin: 32px 0 10px; }
  .eyebrow { font-size: 10px; letter-spacing: 0.1em; }
  .lede { font-size: 16px; line-height: 1.55; margin-bottom: 22px; }
  p.body { font-size: 15px; line-height: 1.65; }
  .welcome { min-height: calc(100dvh - 120px); gap: 14px; padding-bottom: 16px; }
  .welcome h1 { font-size: 36px; line-height: 1.08; letter-spacing: -0.025em; }
  .welcome .lede { font-size: 16px; }
  .welcome .wave { font-size: 12px; padding: 5px 11px; }
  .welcome .quick-facts {
    flex-direction: column;
    gap: 8px;
    font-size: 13px;
    margin-top: 12px;
  }
  .welcome .cta-row { gap: 8px; }
  .sec { margin-top: 48px; }
  .sec-eyebrow { font-size: 10px; }
  .sec-title { font-size: 22px; margin-bottom: 10px; }
  .sec-lede { font-size: 15px; margin-bottom: 22px; }

  /* === Stack components vertically === */
  .hero { flex-direction: column; gap: 18px; }
  .avatar { width: 64px; height: 64px; font-size: 24px; }
  .outcome-grid { grid-template-columns: 1fr; }
  .image-row { grid-template-columns: 1fr; }
  .mini-process {
    grid-template-columns: 1fr;
    padding: 14px;
    gap: 14px;
    border-radius: 12px;
  }
  .mini-process .step .ds { font-size: 12px; }
  .contact-grid { grid-template-columns: 1fr; }
  .contact-form { padding: 18px; }
  .contact-form .row { flex-direction: column; gap: 12px; }
  .calendly-card { padding: 18px; }
  .focus-grid { grid-template-columns: 1fr; }
  .actions { gap: 8px; }
  .pill-list { gap: 6px; margin-bottom: 16px; }

  /* Meta row — stack as a clean 2-col grid (or 1 col on very narrow) */
  .meta-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px 20px;
    padding: 16px 0;
    margin: 22px 0 24px;
  }

  /* Impact bar: stack label/value above the track */
  .impact-bar {
    grid-template-columns: 1fr auto;
    grid-template-areas:
      "lbl val"
      "trk trk";
    gap: 6px 12px;
    margin-bottom: 14px;
  }
  .impact-bar .lbl { grid-area: lbl; }
  .impact-bar .val { grid-area: val; }
  .impact-bar .track { grid-area: trk; height: 8px; }
  .impact-chart { padding: 14px; }

  /* Projects list — single column with bigger cards */
  .projects-list-grid {
    grid-template-columns: 1fr;
    gap: 14px;
    margin-top: 18px;
  }
  .pl-card { padding: 16px; }
  .pl-card .pl-thumb { aspect-ratio: 16 / 8; font-size: 16px; }
  .pl-card .pl-title { font-size: 16px; }
  .pl-card .pl-tag { font-size: 13px; }

  /* Hero artwork — taller on mobile for more visual presence */
  .artwork {
    aspect-ratio: 4 / 5;
    border-radius: 18px;
    font-size: 28px;
    max-width: 100%;
    margin-top: 12px;
    margin-bottom: 24px;
  }

  /* Bleed-left fallback (still used elsewhere if class was applied) */
  .bleed-left { margin-left: 0; margin-right: 0; width: 100%; padding-left: 0; padding-right: 0; }

  /* Image placeholders sized down */
  .image-placeholder { padding: 18px; aspect-ratio: 16 / 10; margin: 12px 0; }
  .image-placeholder.wide { aspect-ratio: 16 / 10; }
  .image-placeholder.tall { aspect-ratio: 4 / 5; }

  /* Process flow — stack into 2 cols then 1 if needed */
  .process-flow { grid-template-columns: repeat(2, 1fr); gap: 18px; }
  .process-flow::before { display: none; }
  .process-step .num { width: 44px; height: 44px; font-size: 16px; }
  .process-step .label { font-size: 13px; }
  .process-step .desc { font-size: 12px; }

  /* Contact meta */
  .contact-meta { gap: 10px; flex-direction: column; }

  /* Panel nav hint — stack on mobile */
  .panel-nav-hint {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    margin-top: 36px;
  }
  .panel-nav-hint .nav-side.nav-right { text-align: left; }
}

