  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.06);
  /* Only vertical pans go to the panel; horizontal is reserved for our
     swipe-back gesture, and never bubbles to the underlying scroller. */
  touch-action: pan-y;
}

