  /* =========================================================
     MOBILE OVERRIDES — kept at the end of the stylesheet so
     these win over equal-specificity desktop rules at <=768px.
     ========================================================= */
  @media (max-width: 768px) {
    :root {
      --sidebar-width: 0px;
      --sidebar-gap: 0px;
      --bleed: 0px;
      --content-offset: 0px;
      --snap-offset: 0px;
      --pad-left: 20px;
      --pad-right: 20px;
    }

    /* Fully hide the desktop sidebar */
    .sidebar,
    aside.sidebar { display: none !important; }

    /* === Disable horizontal swipe between About and Projects ===
       Both panels become positioned overlays, swapped by class. */
    .content {
      overflow: hidden;
      display: block;
      scroll-snap-type: none;
    }
    .content-spacer { display: none; }

    .panel {
      width: 100vw;
      flex: none;
      height: 100dvh;
      padding: 24px 20px 96px 20px;
    }
    .panel[data-id="about"],
    .panel[data-id="projects-list"] {
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100dvh;
      overflow-y: auto;
      overflow-x: hidden;
      z-index: 5;
      transform: translateX(0);
      transition: transform 0.32s cubic-bezier(.2,.8,.2,1);
      box-sizing: border-box;
      touch-action: pan-y;
    }
    .panel[data-id="projects-list"] { transform: translateX(100%); }
    body.show-projects .panel[data-id="about"] { transform: translateX(-8%); }
    body.show-projects .panel[data-id="projects-list"] { transform: translateX(0); }

    .panel-inner { max-width: 100%; }
    .panel:not(.active) .panel-inner { opacity: 1; }

    /* === Project panels — slide-in overlays === */
    .panel.is-project {
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100dvh;
      flex: none;
      transform: translateX(100%);
      transition: transform 0.32s cubic-bezier(.2,.8,.2,1);
      z-index: 40;
      background: var(--bg);
      overflow-y: auto;
      overflow-x: hidden;
      padding: 0 0 60px 0; /* sticky header sits at the very top */
      box-shadow: -8px 0 24px rgba(0, 0, 0, 0.06);
      touch-action: pan-y;
    }
    .panel.is-project.is-open { transform: translateX(0); }
    .panel.is-project.is-dragging { transition: none; }
    .panel.is-project .panel-inner {
      opacity: 1 !important;
      padding: 0 20px;
      max-width: 100%;
    }

    /* === Sticky back button at the VERY top of the project page === */
    .mobile-back-btn {
      display: flex;
      align-items: center;
      gap: 8px;
      position: sticky;
      top: 0;
      width: 100%;
      padding: 14px 16px;
      margin: 0 0 8px;
      z-index: 10;
      background: rgba(245, 245, 247, 0.82);
      backdrop-filter: saturate(180%) blur(24px);
      -webkit-backdrop-filter: saturate(180%) blur(24px);
      border: none;
      border-bottom: 1px solid rgba(0, 0, 0, 0.05);
      border-radius: 0;
      font-family: inherit;
      font-size: 15px;
      font-weight: 500;
      color: var(--accent);
