function closeProjectMobile() {
  if (openProjectPanel) {
    openProjectPanel.classList.remove('is-open');
    openProjectPanel = null;
  }
  document.body.classList.remove('project-open');
  // Keep the user on the Projects tab after closing a project
  document.body.classList.add('show-projects');
  setActive('projects-list');
}

function scrollToTarget(id) {
  // === Mobile navigation: no horizontal scrolling between panels. ===
  if (isMobile()) {
    // Project panels slide in as overlays
    if (projects.some(p => p.id === id)) {
      openProjectMobile(id);
      return;
    }
    // Close any open project first
    if (openProjectPanel) closeProjectMobile();
    // Switch between About and Projects-list by toggling a body class
    if (id === 'about') {
      document.body.classList.remove('show-projects');
    } else if (id === 'projects-list') {
      document.body.classList.add('show-projects');
    }
    return;
  }

  let panel = panels.find(p => p.dataset.id === id);
  if (!panel) return;
  // If panel is hidden at this breakpoint (e.g., projects-list on desktop),
  // fall back to the nearest visible neighbour so navigation never dead-ends.
  if (panel.offsetWidth === 0) {
    const idx = order.indexOf(id);
    let fallback = null;
    for (let i = idx - 1; i >= 0 && !fallback; i--) {
      const c = panels.find(p => p.dataset.id === order[i]);
      if (c && c.offsetWidth > 0) fallback = c;
    }
    if (!fallback) for (let i = idx + 1; i < order.length && !fallback; i++) {
      const c = panels.find(p => p.dataset.id === order[i]);
      if (c && c.offsetWidth > 0) fallback = c;
    }
    if (!fallback) return;
    panel = fallback;
  }

