/* === Sliding pill indicator behind the active bottom-nav tab === */
const bnIndicator = document.querySelector('.bn-indicator');
const bnNav = document.getElementById('bottomNav');
function positionBnIndicator(activeTab) {
  if (!bnIndicator || !activeTab || !bnNav) return;
  const navBox = bnNav.getBoundingClientRect();
  const tabBox = activeTab.getBoundingClientRect();
  // Coordinates relative to the nav's padding box
  const left = tabBox.left - navBox.left;
  const width = tabBox.width;
  // First positioning shouldn't animate — set the .is-ready flag afterward
  bnIndicator.style.transform = `translateX(${left}px)`;
  bnIndicator.style.width = `${width}px`;
  if (!bnIndicator.classList.contains('is-ready')) {
    // Force browser to apply the initial position before enabling transitions
    requestAnimationFrame(() => bnIndicator.classList.add('is-ready'));
  }
}
// Re-position on resize / orientation change
window.addEventListener('resize', () => {
  const active = document.querySelector('.bn-tab.active');
  positionBnIndicator(active);
});

