// Re-position on resize / orientation change
window.addEventListener('resize', () => {
  const active = document.querySelector('.bn-tab.active');
  positionBnIndicator(active);
});

/* =================================================================
   iOS 26 Liquid Glass: tab-bar minimize-on-scroll behavior.
   Apple's `.tabBarMinimizeBehavior(.onScrollDown)` — the bar recedes
   when the user scrolls *down* and re-expands when scrolling *up*.
   We watch the currently visible mobile panel (about, projects-list,
   or an open project) and toggle a `nav-minimized` class on <body>.
   ================================================================= */
(function initNavMinimize() {
  const MIN_SCROLL_TO_TRIGGER = 6; // ignore micro-jitter
  const SHOW_NEAR_TOP = 24;        // always show near the top
  let lastScrollTop = 0;
  let ticking = false;

  function getActiveScroller() {
    if (openProjectPanel) return openProjectPanel;
    if (document.body.classList.contains('show-projects')) {
      return document.querySelector('.panel[data-id="projects-list"]');
    }
    return document.querySelector('.panel[data-id="about"]');
  }

  function onPanelScroll() {
    if (!isMobile()) return;
    const scroller = getActiveScroller();
    if (!scroller) return;
    const st = scroller.scrollTop;
    const delta = st - lastScrollTop;

    if (st <= SHOW_NEAR_TOP) {
      document.body.classList.remove('nav-minimized');
    } else if (delta > MIN_SCROLL_TO_TRIGGER) {
      // scrolling down → minimize
      document.body.classList.add('nav-minimized');
    } else if (delta < -MIN_SCROLL_TO_TRIGGER) {
      // scrolling up → expand
      document.body.classList.remove('nav-minimized');
    }
    lastScrollTop = st;
    ticking = false;
  }

  function schedule() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(onPanelScroll);
  }

  // Attach a scroll listener to every panel (cheap; only one is visible at a time)
  panels.forEach(panel => {
    panel.addEventListener('scroll', () => {
      // Track each panel's scroll independently; reset baseline when switching
      if (getActiveScroller() === panel) {
        schedule();
      } else {
        lastScrollTop = panel.scrollTop;
      }
    }, { passive: true });
  });

  // Reset baseline when the active scroller changes (tab switch, project open/close)
  function resetBaseline() {
    const s = getActiveScroller();
    lastScrollTop = s ? s.scrollTop : 0;
    document.body.classList.remove('nav-minimized');
  }
  // Hook into the existing functions
  const _open = openProjectMobile;
  openProjectMobile = function(id) { _open(id); resetBaseline(); };
  const _close = closeProjectMobile;
  closeProjectMobile = function() { _close(); resetBaseline(); };

  // Also reset on tab change via bn-tab clicks
  document.querySelectorAll('.bn-tab').forEach(tab => {
    tab.addEventListener('click', () => setTimeout(resetBaseline, 50), { passive: true });
  });

  // If user resizes from desktop to mobile, ensure clean state
  mobileMQ.addEventListener('change', e => {
    if (!e.matches) document.body.classList.remove('nav-minimized');
  });
})();

