file.content:
/* ===== Projects list (deep dive entry on mobile) ===== */
.panel[data-id="projects-list"] {
  display: none;
}
.projects-list-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 22px;
}
.pl-card {
  text-align: left;
  background: white;
  border: 1px solid var(--divider);
  border-radius: 16px;
  padding: 14px;
  cursor: pointer;
  transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
  font-family: inherit;
  color: inherit;
}
.pl-card:hover, .pl-card:focus-visible {
  transform: translateY(-2px);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.06);
  border-color: rgba(0, 122, 255, 0.25);
  outline: none;
}
.pl-card .pl-thumb {
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: 10px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  letter-spacing: -0.01em;
  font-size: 14px;
  position: relative;
  overflow: hidden;
}
.pl-card .pl-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 28% 28%, rgba(255,255,255,0.32), transparent 55%);
}
.pl-card .pl-thumb span { position: relative; z-index: 1; }
.pl-card .pl-title { font-size: 14px; font-weight: 600; margin-bottom: 2px; }
.pl-card .pl-tag { font-size: 12px; color: var(--text-tertiary); }
.pl-card .pl-arrow {
  margin-top: 10px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 500;
}

